1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<title>Tensor Core</title>
6	<link rel="stylesheet" href="../viz-base.css">
7	<script src="../viz-base.js"></script>
8	<style>
9	  .main { display:flex; gap:24px; max-width:1200px; margin:0 auto; justify-content:center; align-items:flex-start; flex-wrap:wrap; }
10	  .mat-box { background:var(--surface); border-radius:10px; padding:14px; border:1px solid var(--border);
11	    box-shadow:0 1px 3px rgba(0,0,0,.06); text-align:center; }
12	  .mat-box h2 { font-size:14px; font-weight:700; margin-bottom:4px; }
13	  .mat-box .dims { font-size:11px; color:var(--dim); margin-bottom:8px; font-weight:600; }
14	
15	  .grid { display:inline-grid; gap:1px; }
16	  .cell {
17	    border-radius:3px; display:flex; align-items:center; justify-content:center;
18	    font-size:8px; font-weight:700; border:2px solid transparent; transition:all .15s;
19	    cursor:pointer; min-width:0; color:#fff; text-shadow:0 1px 1px rgba(0,0,0,.2);
20	  }
21	  .cell.idle { background:var(--color-cell-bg); color:var(--text); text-shadow:none; }
22	  .cell.active { border-color:#222; border-width:2px; z-index:1; }
23	  .cell.dim { background:#e2e5ea !important; color:#aaa !important; text-shadow:none !important; opacity:1; }
24	
25	  .op { font-size:22px; display:flex; align-items:center; justify-content:center; color:var(--dim);
26	    font-weight:700; padding:0 6px; align-self:center; }
27	  .eq { font-size:18px; display:flex; align-items:center; justify-content:center; color:var(--dim);
28	    font-weight:700; padding:0 6px; align-self:center; }
29	
30	  .anim-bar { max-width:1200px; margin:18px auto 0; display:flex; gap:8px; justify-content:center; align-items:center; }
31	  #kbar { display:flex; gap:2px; }
32	  .anim-bar .lbl { font-size:12px; color:var(--dim); font-weight:600; }
33	  .kb { width:36px; height:30px; border:1px solid var(--border); background:var(--surface); color:var(--text);
34	    cursor:pointer; border-radius:0; font-size:12px; font-family:inherit; display:flex; align-items:center;
35	    justify-content:center; transition:all .12s; font-weight:600; }
36	  .kb:hover { background:#eef0f4; }
37	  .kb.on { background:var(--accent); border-color:var(--accent); color:#fff; }
38	  .kb.done { background:#93c5fd; border-color:#93c5fd; color:#fff; }
39	
40	  .formula-box { max-width:1200px; margin:12px auto 0; background:var(--surface); border:1px solid var(--border);
41	    border-radius:8px; padding:10px 16px; text-align:center; font-size:14px;
42	    font-family:'SF Mono','Fira Code',monospace; color:var(--accent); font-weight:600; }
43	
44	  .info { max-width:1200px; margin:14px auto 0; text-align:center; font-size:13px; color:var(--dim); font-weight:600; }
45	
46	  .unit-note { max-width:1200px; margin:4px auto 12px; text-align:center; font-size:12px; color:var(--dim); font-weight:600; }
47	
48	  .leg { gap:0; margin-top:12px; }
49	</style>
50	</head>
51	<body>
52	
53	<h1>tcgen05.mma</h1>
54	
55	<div class="controls">
56	  <div><span class="lbl">Transpose A</span>
57	    <div class="bg" id="ta">
58	      <button class="btn on" data-v="0">No</button>
59	      <button class="btn" data-v="1">Yes</button>
60	    </div>
61	  </div>
62	  <div><span class="lbl">Transpose B</span>
63	    <div class="bg" id="tb">
64	      <button class="btn on" data-v="0">No</button>
65	      <button class="btn" data-v="1">Yes</button>
66	    </div>
67	  </div>
68	</div>
69	<div class="controls">
70	  <div><span class="lbl">M (output rows)</span>
71	    <div class="bg" id="mc">
72	      <button class="btn on" data-v="128" disabled>128</button>
73	    </div>
74	  </div>
75	  <div><span class="lbl">N (output cols)</span>
76	    <div class="bg" id="nc">
77	      <button class="btn on" data-v="16">16</button>
78	      <button class="btn" data-v="32">32</button>
79	      <button class="btn" data-v="64">64</button>
80	      <button class="btn" data-v="128">128</button>
81	    </div>
82	  </div>
83	  <div><span class="lbl">K</span>
84	    <div class="bg">
85	      <button class="btn on" disabled>16</button>
86	    </div>
87	  </div>
88	</div>
89	<div class="controls">
90	  <div><span class="lbl">Row group</span><div class="bg" id="rg"></div></div>
91	  <div><span class="lbl">Col group</span><div class="bg" id="cg"></div></div>
92	</div>
93	<div class="unit-note" id="unit-note"></div>
94	
95	<div class="main">
96	  <div class="mat-box" style="border-color:#8b5cf6;">
97	    <h2 style="color:#5b21b6" id="ah">A (SMEM)</h2>
98	    <div class="dims" id="ad"></div>
99	    <div class="grid" id="ga"></div>
100	  </div>
101	  <div class="op">&times;</div>
102	  <div class="mat-box" style="border-color:#8b5cf6;">
103	    <h2 style="color:#5b21b6" id="bh">B (SMEM)</h2>
104	    <div class="dims" id="bd"></div>
105	    <div class="grid" id="gb"></div>
106	  </div>
107	  <div style="display:flex; flex-direction:column; align-items:center; gap:4px; align-self:center; padding:0 4px;">
108	    <div style="border:2.5px solid #059669; border-radius:8px; padding:6px 12px; text-align:center;">
109	      <div style="font-size:11px; font-weight:700; color:#065f46;">Tensor Core</div>
110	      <div style="font-size:8px; color:#059669; font-weight:600;">tcgen05.mma</div>
111	    </div>
112	    <div style="color:#059669; font-size:18px; font-weight:700; line-height:1;">&rarr;</div>
113	  </div>
114	  <div class="mat-box" style="border-color:#f59e0b;">
115	    <h2 style="color:#c2410c">C (TMEM)</h2>
116	    <div class="dims" id="cd"></div>
117	    <div style="display:flex; align-items:flex-start; gap:4px;">
118	      <div style="writing-mode:vertical-lr; transform:rotate(180deg); font-size:9px; font-weight:700; color:#f59e0b; display:flex; align-items:center; justify-content:center;">128 Lanes (M)</div>
119	      <div>
120	        <div class="grid" id="gc"></div>
121	        <div style="text-align:center; font-size:9px; font-weight:700; color:#f59e0b; margin-top:2px;" id="col-label">Col (N) — allocated by <code style="font-size:8px; border:1px solid #f59e0b; border-radius:3px; padding:0 3px;">tmem.alloc</code></div>
122	      </div>
123	    </div>
124	  </div>
125	</div>
126	
127	<div class="anim-bar">
128	  <span class="lbl">K iteration:</span>
129	  <div id="kbar"></div>
130	</div>
131	
132	<div class="formula-box" id="fbox"></div>
133	<div class="info" id="inf"></div>
134	
135	<div style="max-width:1200px; margin:10px auto 0; display:flex; gap:12px; justify-content:center; flex-wrap:wrap;">
136	  <div style="border:1px solid #8b5cf6; border-radius:8px; padding:8px 14px; font-family:'SF Mono','Fira Code',monospace; font-size:11px;">
137	    <div style="font-weight:700; color:#5b21b6; margin-bottom:4px;">SMEM Descriptor (A, B)</div>
138	    <div style="color:#475569;">smem_desc = <span style="color:#8b5cf6;">base_addr</span> | <span style="color:#8b5cf6;">leading_byte_offset</span> | <span style="color:#8b5cf6;">stride_byte_offset</span> | <span style="color:#8b5cf6;">start_addr_off</span></div>
139	  </div>
140	  <div style="border:1px solid #059669; border-radius:8px; padding:8px 14px; font-family:'SF Mono','Fira Code',monospace; font-size:11px;">
141	    <div style="font-weight:700; color:#065f46; margin-bottom:4px;">tcgen05.mma PTX</div>
142	    <div style="color:#475569;">tcgen05.mma.cta_group::1.kind::f16 [<span style="color:#059669;">taddr</span>], <span style="color:#8b5cf6;">a_desc</span>, <span style="color:#8b5cf6;">b_desc</span>, <span style="color:#f59e0b;">idesc</span>,</div>
143	    <div style="color:#475569; padding-left:20px;">{<span style="color:#64748b;">mask0, mask1, mask2, mask3</span>}, <span style="color:#059669;">enable</span>;</div>
144	  </div>
145	</div>
146	
147	<script>
148	// SMEM purple for A/B, TMEM orange for C (matching Blackwell arch slide)
149	const BK = ['#8b5cf6','#8b5cf6','#d95555','#45b5a5','#f59e0b','#e0b828','#9d6eb5','#e87888'];
150	const TOTAL = 128, BLOCK = 16;
151	const BCOUNT = TOTAL / BLOCK; // 8x8 blocks
152	// M = output rows, N = output cols. M fixed at 128 for tcgen05.
153	const ST = { m: 128, n: 16, k: 0, rg: 0, cg: 0, tA: false, tB: false, playing: false, timer: null };
154	
155	function rebuildGroups() {
156	  const mBlocks = ST.m / BLOCK; // row blocks
157	  const nBlocks = ST.n / BLOCK; // col blocks
158	  const mGroups = BCOUNT / mBlocks;
159	  const nGroups = BCOUNT / nBlocks;
160	  // Clamp
161	  if (ST.rg >= mGroups) ST.rg = 0;
162	  if (ST.cg >= nGroups) ST.cg = 0;
163	
164	  const rg = document.getElementById('rg'); rg.innerHTML = '';
165	  for (let i = 0; i < mGroups; i++) {
166	    const b = mk('button', 'btn' + (ST.rg === i ? ' on' : '')); b.textContent = i;
167	    b.onclick = (v => () => { ST.rg = v; rg.querySelectorAll('.btn').forEach(x => x.classList.remove('on')); b.classList.add('on'); draw(); })(i);
168	    rg.appendChild(b);
169	  }
170	  const cg = document.getElementById('cg'); cg.innerHTML = '';
171	  for (let i = 0; i < nGroups; i++) {
172	    const b = mk('button', 'btn' + (ST.cg === i ? ' on' : '')); b.textContent = i;
173	    b.onclick = (v => () => { ST.cg = v; cg.querySelectorAll('.btn').forEach(x => x.classList.remove('on')); b.classList.add('on'); draw(); })(i);
174	    cg.appendChild(b);
175	  }
176	}
177	
178	function draw() {
179	  const mBlocks = ST.m / BLOCK; // row blocks
180	  const nBlocks = ST.n / BLOCK; // col blocks
181	  const totalK = BCOUNT;
182	  const sz = Math.max(14, Math.min(28, 240 / BCOUNT));
183	  const tA = ST.tA, tB = ST.tB;
184	  const rOff = ST.rg * mBlocks; // row offset in blocks
185	  const cOff = ST.cg * nBlocks; // col offset in blocks
186	
187	  // Headers
188	  document.getElementById('ah').textContent = (tA ? 'A\u1d40' : 'A') + ' (SMEM)';
189	  document.getElementById('bh').textContent = (tB ? 'B\u1d40' : 'B') + ' (SMEM)';
190	
191	  // Dims
192	  const mEnd = rOff + mBlocks - 1;
193	  const nEnd = cOff + nBlocks - 1;
194	  document.getElementById('unit-note').textContent =
195	    'Each cell represents one 16\u00d716 element block; the current C tile is ' +
196	    mBlocks + '\u00d7' + nBlocks + ' cells = ' + ST.m + '\u00d7' + ST.n + ' elements';
197	  if (tA) {
198	    document.getElementById('ad').textContent = 'K\u00d7M: K block ' + (ST.k < 0 ? 'all' : ST.k) + ', M blocks ' + rOff + '-' + mEnd;
199	  } else {
200	    document.getElementById('ad').textContent = 'M\u00d7K: M blocks ' + rOff + '-' + mEnd + ', K block ' + (ST.k < 0 ? 'all' : ST.k);
201	  }
202	  if (tB) {
203	    document.getElementById('bd').textContent = 'N\u00d7K: N blocks ' + cOff + '-' + nEnd + ', K block ' + (ST.k < 0 ? 'all' : ST.k);
204	  } else {
205	    document.getElementById('bd').textContent = 'K\u00d7N: K block ' + (ST.k < 0 ? 'all' : ST.k) + ', N blocks ' + cOff + '-' + nEnd;
206	  }
207	  document.getElementById('cd').textContent = ST.m + '\u00d7' + ST.n + ' accumulator';
208	
209	  // Matrix A: 8x8 grid — highlight M-rows
210	  const ga = document.getElementById('ga'); ga.innerHTML = '';
211	  ga.style.gridTemplateColumns = 'repeat(' + BCOUNT + ',' + sz + 'px)';
212	  for (let r = 0; r < BCOUNT; r++) {
213	    for (let c = 0; c < BCOUNT; c++) {
214	      const d = mk('div', 'cell');
215	      d.style.width = sz + 'px'; d.style.height = sz + 'px';
216	      const cellM = tA ? c : r;
217	      const cellK = tA ? r : c;
218	      const inM = cellM >= rOff && cellM < rOff + mBlocks;
219	      if (inM) {
220	        if (cellK === ST.k) { d.style.background = BK[0]; d.classList.add('active'); }
221	        else if (cellK < ST.k) { d.style.background = BK[0]; d.style.opacity = '.4'; }
222	        else { d.classList.add('idle', 'dim'); }
223	      } else {
224	        d.classList.add('idle', 'dim');
225	      }
226	      ga.appendChild(d);
227	    }
228	  }
229	
230	  // Matrix B: 8x8 grid — highlight N-cols
231	  const gb = document.getElementById('gb'); gb.innerHTML = '';
232	  gb.style.gridTemplateColumns = 'repeat(' + BCOUNT + ',' + sz + 'px)';
233	  for (let r = 0; r < BCOUNT; r++) {
234	    for (let c = 0; c < BCOUNT; c++) {
235	      const d = mk('div', 'cell');
236	      d.style.width = sz + 'px'; d.style.height = sz + 'px';
237	      const cellK = tB ? c : r;
238	      const cellN = tB ? r : c;
239	      const inN = cellN >= cOff && cellN < cOff + nBlocks;
240	      if (inN) {
241	        if (cellK === ST.k) { d.style.background = BK[1]; d.classList.add('active'); }
242	        else if (cellK < ST.k) { d.style.background = BK[1]; d.style.opacity = '.4'; }
243	        else { d.classList.add('idle', 'dim'); }
244	      } else {
245	        d.classList.add('idle', 'dim');
246	      }
247	      gb.appendChild(d);
248	    }
249	  }
250	
251	  // C: always 8×8 (128×128 TMEM), allocated region green, rest grey
252	  const gc = document.getElementById('gc'); gc.innerHTML = '';
253	  gc.style.gridTemplateColumns = 'repeat(' + BCOUNT + ',' + sz + 'px)';
254	  for (let r = 0; r < BCOUNT; r++) {
255	    for (let c = 0; c < BCOUNT; c++) {
256	      const d = mk('div', 'cell');
257	      d.style.width = sz + 'px'; d.style.height = sz + 'px';
258	      if (r >= rOff && r < rOff + mBlocks && c >= cOff && c < cOff + nBlocks) {
259	        d.style.background = BK[4]; d.classList.add('active');
260	      } else {
261	        d.classList.add('idle', 'dim');
262	      }
263	      gc.appendChild(d);
264	    }
265	  }
266	  // K bar
267	  const kbar = document.getElementById('kbar'); kbar.innerHTML = '';
268	  const pb = mk('button', 'kb'); pb.style.width = '36px'; pb.style.fontSize = '16px';
269	  pb.innerHTML = '&#x25b7;';
270	  pb.onclick = () => {
271	    if (ST.playing) { clearInterval(ST.timer); ST.playing = false; draw(); return; }
272	    ST.k = 0; ST.playing = true; draw();
273	    ST.timer = setInterval(() => {
274	      ST.k++;
275	      if (ST.k >= totalK) { ST.k = 0; ST.playing = false; clearInterval(ST.timer); }
276	      draw();
277	    }, 600);
278	  };
279	  kbar.appendChild(pb);
280	  for (let i = 0; i < totalK; i++) {
281	    const b = mk('button', 'kb');
282	    if (ST.k === i) b.classList.add('on');
283	    else if (i < ST.k) b.classList.add('done');
284	    b.textContent = i;
285	    b.onclick = (v => () => { ST.k = v; draw(); })(i);
286	    kbar.appendChild(b);
287	  }
288	
289	  // Formula
290	  const fbox = document.getElementById('fbox');
291	  const aRef = tA ? 'A\u1d40[k, m]' : 'A[m, k]';
292	  const bRef = tB ? 'B\u1d40[n, k]' : 'B[k, n]';
293	  const accum = ST.k === 0 ? 0 : 1;
294	  const assign = accum ? '+=' : '=';
295	  fbox.textContent = 'MMA m' + ST.m + 'n' + ST.n + 'k16, accum=' + accum + '  |  C ' + assign + ' ' + aRef + ' \u00d7 ' + bRef;
296	
297	  // Info
298	  const inf = document.getElementById('inf');
299	  inf.textContent = 'K step ' + ST.k + ' of ' + totalK + '  |  A reads ' + mBlocks +
300	    ' 16\u00d716 block' + (mBlocks > 1 ? 's' : '') + ', B reads ' + nBlocks +
301	    ' 16\u00d716 block' + (nBlocks > 1 ? 's' : '');
302	}
303	
304	function mk(t, c) { const d = document.createElement(t); if (c) d.className = c; return d; }
305	
306	(function init() {
307	  document.getElementById('mc').onclick = e => {
308	    const b = e.target.closest('.btn'); if (!b) return;
309	    ST.m = +b.dataset.v;
310	    document.querySelectorAll('#mc .btn').forEach(x => x.classList.remove('on')); b.classList.add('on');
311	    rebuildGroups(); draw();
312	  };
313	  document.getElementById('nc').onclick = e => {
314	    const b = e.target.closest('.btn'); if (!b) return;
315	    ST.n = +b.dataset.v;
316	    document.querySelectorAll('#nc .btn').forEach(x => x.classList.remove('on')); b.classList.add('on');
317	    rebuildGroups(); draw();
318	  };
319	  // Default M=128 selected
320	  ST.m = 128;
321	  document.querySelectorAll('#mc .btn').forEach(x => x.classList.remove('on'));
322	  document.querySelector('#mc .btn[data-v="128"]').classList.add('on');
323	  document.getElementById('ta').onclick = e => {
324	    const b = e.target.closest('.btn'); if (!b) return;
325	    ST.tA = b.dataset.v === '1';
326	    document.querySelectorAll('#ta .btn').forEach(x => x.classList.remove('on')); b.classList.add('on');
327	    draw();
328	  };
329	  document.getElementById('tb').onclick = e => {
330	    const b = e.target.closest('.btn'); if (!b) return;
331	    ST.tB = b.dataset.v === '1';
332	    document.querySelectorAll('#tb .btn').forEach(x => x.classList.remove('on')); b.classList.add('on');
333	    draw();
334	  };
335	  rebuildGroups();
336	  draw();
337	})();
338	</script>
339	</body>
340	</html>
